create extension if not exists "pgcrypto";
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,email text,avatar_url text,job_title text,phone text,department_id uuid,role text default 'employee' check(role in ('employee','manager','admin')),status text default 'active' check(status in ('active','invited','suspended')),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.departments(id uuid primary key default gen_random_uuid(),name text not null unique,description text,manager_id uuid references public.profiles(id) on delete set null,created_at timestamptz default now());
alter table public.profiles add constraint profiles_department_fk foreign key(department_id) references public.departments(id) on delete set null;
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),name text,is_group boolean default false,created_by uuid references public.profiles(id) on delete set null,created_at timestamptz default now());
create table if not exists public.conversation_members(conversation_id uuid references public.conversations(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,joined_at timestamptz default now(),last_read_at timestamptz,primary key(conversation_id,user_id));
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,body text not null,reply_to_id uuid references public.messages(id) on delete set null,created_at timestamptz default now(),edited_at timestamptz);
create table if not exists public.message_attachments(id uuid primary key default gen_random_uuid(),message_id uuid references public.messages(id) on delete cascade,storage_path text not null,file_name text not null,mime_type text,file_size bigint,created_at timestamptz default now());
create table if not exists public.events(id uuid primary key default gen_random_uuid(),title text not null,description text,start_at timestamptz not null,end_at timestamptz,location text,created_by uuid references public.profiles(id) on delete set null,created_at timestamptz default now());
create table if not exists public.event_attendees(event_id uuid references public.events(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,status text default 'invited',primary key(event_id,user_id));
create table if not exists public.attendance(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,work_date date not null,clock_in timestamptz,clock_out timestamptz,status text default 'present',unique(user_id,work_date));
create table if not exists public.leave_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,type text not null,start_date date not null,end_date date not null,reason text,status text default 'pending' check(status in ('pending','approved','rejected','cancelled')),reviewed_by uuid references public.profiles(id) on delete set null,reviewed_at timestamptz,created_at timestamptz default now());
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),title text not null,description text,status text default 'todo',priority text default 'medium',assignee_id uuid references public.profiles(id) on delete set null,created_by uuid references public.profiles(id) on delete set null,due_date date,created_at timestamptz default now());
create table if not exists public.task_comments(id uuid primary key default gen_random_uuid(),task_id uuid references public.tasks(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,body text not null,created_at timestamptz default now());
create table if not exists public.documents(id uuid primary key default gen_random_uuid(),name text not null,storage_path text not null,is_folder boolean default false,parent_id uuid references public.documents(id) on delete cascade,owner_id uuid references public.profiles(id) on delete set null,created_at timestamptz default now());
create table if not exists public.announcements(id uuid primary key default gen_random_uuid(),title text not null,body text not null,author_id uuid references public.profiles(id) on delete set null,published_at timestamptz default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null,body text,kind text,read_at timestamptz,created_at timestamptz default now());
create table if not exists public.approvals(id uuid primary key default gen_random_uuid(),requester_id uuid references public.profiles(id) on delete set null,type text not null,title text not null,details jsonb default '{}'::jsonb,status text default 'pending',reviewer_id uuid references public.profiles(id) on delete set null,created_at timestamptz default now(),reviewed_at timestamptz);
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id) on delete set null,action text not null,entity_type text,entity_id uuid,metadata jsonb default '{}'::jsonb,created_at timestamptz default now());
create index if not exists messages_conversation_created_idx on public.messages(conversation_id,created_at desc);create index if not exists notifications_user_idx on public.notifications(user_id,created_at desc);create index if not exists tasks_assignee_idx on public.tasks(assignee_id,status);create index if not exists events_start_idx on public.events(start_at);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','New user'),new.email) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;alter table public.departments enable row level security;alter table public.conversations enable row level security;alter table public.conversation_members enable row level security;alter table public.messages enable row level security;alter table public.events enable row level security;alter table public.event_attendees enable row level security;alter table public.attendance enable row level security;alter table public.leave_requests enable row level security;alter table public.tasks enable row level security;alter table public.task_comments enable row level security;alter table public.documents enable row level security;alter table public.announcements enable row level security;alter table public.notifications enable row level security;alter table public.approvals enable row level security;alter table public.audit_logs enable row level security;
create policy "profiles authenticated read" on public.profiles for select to authenticated using(true);create policy "profiles own update" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);create policy "profiles own insert" on public.profiles for insert to authenticated with check(auth.uid()=id);create policy "departments authenticated read" on public.departments for select to authenticated using(true);create policy "conversation members read own" on public.conversation_members for select to authenticated using(user_id=auth.uid());create policy "messages members read" on public.messages for select to authenticated using(exists(select 1 from public.conversation_members cm where cm.conversation_id=messages.conversation_id and cm.user_id=auth.uid()));create policy "messages members insert" on public.messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.conversation_members cm where cm.conversation_id=messages.conversation_id and cm.user_id=auth.uid()));create policy "events authenticated read" on public.events for select to authenticated using(true);create policy "tasks authenticated read" on public.tasks for select to authenticated using(true);create policy "tasks own create" on public.tasks for insert to authenticated with check(created_by=auth.uid());create policy "notifications own" on public.notifications for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "announcements authenticated read" on public.announcements for select to authenticated using(true);